mapper.select:
SELECT plan_id, plan_type, plan_title, plan_date, plan_due, plan_time, user_id
FROM plan
WHERE plan_id = #{planId}

mapper.update:
UPDATE plan 
SET plan_title = #{planTitle}, plan_date = #{planDate}
WHERE plan_id = #{planId}

UPDATE plan 
SET plan_title = #{planTitle}, plan_date = #{planDate}, plan_due = #{planDue}
WHERE plan_id = #{planId}

UPDATE plan 
SET plan_title = #{planTitle}, plan_date = #{planDate}, plan_time = #{planTime}
WHERE plan_id = #{planId}
